import {gunzipSync} from 'node:zlib';
import {extractAttachment} from '../vendor/pdf-library.mjs';

try {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  const input = Buffer.concat(chunks);
  if (input.length > 65536 || input.subarray(0, 7).toString() !== 'SHOPPDF') throw new Error('invalid input');
  // Check the inflated size before handing the document to the unbounded vendor API.
  gunzipSync(input.subarray(7), {maxOutputLength: 1024 * 1024});
  const xml = await extractAttachment(input);
  if (Buffer.byteLength(xml) > 1024 * 1024) throw new Error('output too large');
  const title = /<title>(.*?)<\/title>/s.exec(xml)?.[1];
  if (!title) throw new Error('missing title');
  process.stdout.write(JSON.stringify({kind: 'proposal', title}));
} catch {
  process.exitCode = 1;
}

