import {spawn} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {readFile} from 'node:fs/promises';

const unreadable = () => ({status: 422, body: {kind: 'unreadable', kept: true}});
const busy = () => ({status: 503, body: {kind: 'busy'}});
const parser = fileURLToPath(new URL('./parser.mjs', import.meta.url));
let active = false;
const queue = [];

function run(buffer) {
  return new Promise((resolve) => {
    let child;
    let monitor;
    let timer;
    let interval;
    let done = false;
    let output = Buffer.alloc(0);
    let started = false;
    const supervised = () => {
      if (!started && !done) { started = true; child.stdin.end(buffer); }
    };
    const finish = (result) => {
      if (done) return;
      done = true;
      clearTimeout(timer);
      clearInterval(interval);
      if (monitor) monitor.kill('SIGKILL');
      if (child) child.kill('SIGKILL');
      resolve(result);
    };
    try {
      child = spawn(process.execPath, [parser], {env: {}, stdio: ['pipe', 'pipe', 'ignore']});
      child.on('error', () => finish(unreadable()));
      child.stdin.on('error', () => finish(unreadable()));
      child.stdout.on('error', () => finish(unreadable()));
      child.stdout.on('data', (chunk) => {
        if (output.length + chunk.length > 1024 * 1024) return finish(unreadable());
        output = Buffer.concat([output, chunk]);
      });
      child.on('close', (code) => {
        if (code !== 0) return finish(unreadable());
        try {
          const body = JSON.parse(output.toString());
          if (body.kind !== 'proposal' || typeof body.title !== 'string') throw new Error('invalid result');
          finish({status: 200, body});
        } catch { finish(unreadable()); }
      });
      // Linux exposes RSS without requiring an additional executable in the image.
      // On other systems, ps supplies the same resident-KiB measurement.
      const check = () => {
        if (done || monitor) return;
        if (process.platform === 'linux') {
          monitor = {kill() {}};
          readFile(`/proc/${child.pid}/status`, 'utf8').then((status) => {
            monitor = undefined;
            if (done) return;
            const match = /^VmRSS:\s+(\d+)\s+kB/m.exec(status);
            if (!match || Number(match[1]) > 96 * 1024) finish(unreadable());
            else supervised();
          }, () => { monitor = undefined; if (!done) finish(unreadable()); });
          return;
        }
        try {
          monitor = spawn('/bin/ps', ['-o', 'rss=', '-p', String(child.pid)], {env: {}, stdio: ['ignore', 'pipe', 'ignore']});
          let rss = '';
          monitor.stdout.on('data', (data) => { rss += data; if (rss.length > 100) finish(unreadable()); });
          monitor.on('error', () => finish(unreadable()));
          monitor.on('close', (code) => {
            monitor = undefined;
            if (done) return;
            const value = Number(rss.trim());
            if (code !== 0 || !rss.trim() || !Number.isFinite(value) || value > 96 * 1024) finish(unreadable());
            else supervised();
          });
        } catch { finish(unreadable()); }
      };
      timer = setTimeout(() => finish(unreadable()), 200);
      check();
      interval = setInterval(check, 5);
    } catch { finish(unreadable()); }
  });
}

async function drain(buffer, resolve) {
  active = true;
  try { resolve(await run(buffer)); }
  catch { resolve(unreadable()); }
  finally {
    const next = queue.shift();
    if (next) drain(next.buffer, next.resolve);
    else active = false;
  }
}
export function upload(buffer) {
  if (buffer.length > 65536) return Promise.resolve(unreadable());
  if (active && queue.length >= 2) return Promise.resolve(busy());
  return new Promise((resolve) => {
    if (active) queue.push({buffer, resolve});
    else drain(buffer, resolve);
  });
}

