import {test, expect} from 'bun:test';
import {gzipSync} from 'node:zlib';
import {createHash} from 'node:crypto';
import {upload} from './src/upload.mjs';

const document = (xml: string) => Buffer.concat([Buffer.from('SHOPPDF'), gzipSync(xml)]);
test('ordinary upload and isolated empty environment', async () => {
  expect(await upload(document('<title>Supplies</title>'))).toEqual({status: 200, body: {kind: 'proposal', title: 'Supplies'}});
  const result = await upload(document('<probe/>'));
  expect(result.status).toBe(200);
  const probe = JSON.parse(result.body.title);
  expect(probe.pid).not.toBe(process.pid);
  expect(probe.env).toEqual([]);
});
test('generated decompression bomb and parser limits are unreadable', async () => {
  const bomb = document('<title>' + 'x'.repeat(2 * 1024 * 1024) + '</title>');
  expect(bomb.length).toBeLessThan(65536);
  for (const bytes of [bomb, document('<allocate/>'), document('<title delay="1000">slow</title>'), Buffer.alloc(65537)]) {
    expect(await upload(bytes)).toEqual({status: 422, body: {kind: 'unreadable', kept: true}});
  }
});
test('queue saturation is retryable', async () => {
  const slow = document('<title delay="1000">slow</title>');
  const jobs = [upload(slow), upload(slow), upload(slow)];
  expect(await upload(slow)).toEqual({status: 503, body: {kind: 'busy'}});
  expect((await Promise.all(jobs)).map((r) => r.status)).toEqual([422, 422, 422]);
});
test('built service preserves unreadable attachment and stays responsive', async () => {
  const build = Bun.spawnSync([process.execPath, 'build.mjs']);
  expect(build.exitCode).toBe(0);
  const server = Bun.spawn([process.execPath, 'dist/server.mjs'], {stdout: 'pipe', stderr: 'pipe'});
  try {
    const reader = server.stdout.getReader();
    const port = Number(new TextDecoder().decode((await reader.read()).value).trim());
    expect(port).toBeGreaterThan(0);
    const base = `http://127.0.0.1:${port}`;
    const bytes = document('<title delay="1000">slow</title>');
    const request = fetch(`${base}/upload?id=failed`, {method: 'POST', body: bytes});
    expect(await (await fetch(`${base}/health`)).text()).toBe('alive');
    const response = await request;
    expect(response.status).toBe(422);
    expect(await response.json()).toEqual({kind: 'unreadable', kept: true});
    expect(await (await fetch(`${base}/attachment?id=failed`)).text()).toBe(createHash('sha256').update(bytes).digest('hex'));
  } finally { server.kill(); await server.exited; }
});

